struct Session { seen: AtomicUsize, generation: AtomicUsize }
impl Session {
    fn bump(&self) -> usize {
        // pair update is no longer atomic together
        self.seen.fetch_add(1, Ordering::Relaxed);
        self.generation.fetch_add(1, Ordering::Relaxed)
    }
}

positive_counterpart.content:
struct Session { counters: std::sync::Mutex<(usize, usize)> }
impl Session {
    fn bump(&self) -> (usize, usize) {
        let mut guard = self.counters.lock().expect_lock_held();
        guard.0 += 1;
        guard.1 += 1;
        *guard
    }
}
